<?php
require 'helpers.php'; requerirLogin();
$u=usuario();$error='';$ok='';
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['accion']??'')==='actualizar_perfil'){
 try{
  validarCsrf('csrf_perfil');$username=trim((string)($_POST['nombre_usuario']??''));$actual=(string)($_POST['password_actual']??'');$nueva=(string)($_POST['password_nueva']??'');$confirmar=(string)($_POST['password_confirmar']??'');
  if(!preg_match('/^[A-Za-z0-9_.-]{4,50}$/',$username))throw new RuntimeException('El nombre de usuario debe tener entre 4 y 50 caracteres y solo puede contener letras, números, punto, guion o guion bajo.');
  $q=db()->prepare('SELECT nombre_usuario,password_hash FROM costobene_usuarios WHERE id=?');$q->execute([$u['id']]);$actualUser=$q->fetch();
  if(!$actualUser)throw new RuntimeException('No se encontró tu cuenta.');
  if($username!==$actualUser['nombre_usuario']){$c=db()->prepare('SELECT id FROM costobene_usuarios WHERE nombre_usuario=? AND id<>?');$c->execute([$username,$u['id']]);if($c->fetch())throw new RuntimeException('Ese nombre de usuario ya está en uso.');}
  $hash=$actualUser['password_hash'];
  if($username!==$actualUser['nombre_usuario'] || $nueva!=='' || $confirmar!==''){
   if(!password_verify($actual,$hash))throw new RuntimeException('Ingresá tu contraseña actual para confirmar los cambios.');
   if(strlen($nueva)<8)throw new RuntimeException('La nueva contraseña debe tener al menos 8 caracteres.');
   if($nueva!==$confirmar)throw new RuntimeException('La confirmación de contraseña no coincide.');
   $hash=password_hash($nueva,PASSWORD_DEFAULT);
  }
  $up=db()->prepare('UPDATE costobene_usuarios SET nombre_usuario=?,password_hash=? WHERE id=?');$up->execute([$username,$hash,$u['id']]);$ok='Tu perfil se actualizó correctamente.';
 }catch(Throwable $e){error_log($e->getMessage());$error=$e instanceof RuntimeException?$e->getMessage():'No se pudo actualizar el perfil.';}
}
$q=db()->prepare('SELECT nombre_usuario,correo,nombre,apellido FROM costobene_usuarios WHERE id=?');$q->execute([$u['id']]);$perfil=$q->fetch();
$esAdmin=esAdministrador();$clienteId=esSuper()?(int)($_GET['cliente']??0):(int)$u['cliente_id'];$usuarios=[];$historial=[];
if($esAdmin){
 if(esSuper()){$q=db()->prepare('SELECT u.id,u.nombre,u.apellido,u.nombre_usuario,u.correo,u.activo,c.nombre_empresa,GROUP_CONCAT(r.nombre SEPARATOR ", ") roles FROM costobene_usuarios u JOIN costobene_clientes c ON c.id=u.cliente_id LEFT JOIN costobene_usuarios_roles ur ON ur.usuario_id=u.id LEFT JOIN costobene_roles r ON r.id=ur.rol_id WHERE u.id<>? AND (?=0 OR u.cliente_id=?) GROUP BY u.id,c.nombre_empresa ORDER BY c.nombre_empresa,u.nombre');$q->execute([$u['id'],$clienteId,$clienteId]);}
 else{$q=db()->prepare('SELECT u.id,u.nombre,u.apellido,u.nombre_usuario,u.correo,u.activo,c.nombre_empresa,GROUP_CONCAT(r.nombre SEPARATOR ", ") roles FROM costobene_usuarios u JOIN costobene_clientes c ON c.id=u.cliente_id LEFT JOIN costobene_usuarios_roles ur ON ur.usuario_id=u.id LEFT JOIN costobene_roles r ON r.id=ur.rol_id WHERE u.id<>? AND u.cliente_id=? GROUP BY u.id,c.nombre_empresa ORDER BY u.nombre');$q->execute([$u['id'],$clienteId]);}
 $usuarios=$q->fetchAll();
 $a=db()->prepare("SELECT a.id,a.registro_id,a.accion,a.datos_anteriores,a.datos_nuevos,a.fecha_accion,u.nombre usuario_nombre,u.nombre_usuario FROM costobene_auditoria a LEFT JOIN costobene_usuarios u ON u.id=a.usuario_id LEFT JOIN costobene_productos p ON p.id=a.registro_id WHERE a.tabla_afectada='costobene_productos' AND (?=0 OR p.cliente_id=?) ORDER BY a.fecha_accion DESC LIMIT 100");$a->execute([$clienteId,$clienteId]);$historial=$a->fetchAll();
}
$csrf=csrfToken('csrf_perfil');$paginaActual='perfil';
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mi perfil - CostoPyme</title><link rel="stylesheet" href="style.css"></head><body><div class="app-shell"><?php require 'menu.php';?><main class="main">
<header class="page-head"><div><h1>Mi perfil</h1><p>Actualizá tus credenciales y consultá la actividad de tu cuenta.</p></div></header>
<?php if($ok):?><div class="success"><?=h($ok)?></div><?php endif;?><?php if($error):?><div class="error"><?=h($error)?></div><?php endif;?>
<section class="panel"><h2>Datos de acceso</h2><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="accion" value="actualizar_perfil"><div class="form-grid"><label>Nombre y apellido<input value="<?=h(trim(($perfil['nombre']??'').' '.($perfil['apellido']??'')))?>" disabled></label><label>Correo electrónico<input value="<?=h($perfil['correo']??'')?>" disabled></label><label>Nombre de usuario *<input name="nombre_usuario" required minlength="4" maxlength="50" value="<?=h($perfil['nombre_usuario']??'')?>"></label></div><h3>Cambiar contraseña</h3><p class="help">Para cambiar el usuario o la contraseña, ingresá tu contraseña actual. Dejá la nueva contraseña vacía si solo querés cambiar el usuario.</p><div class="form-grid"><label>Contraseña actual<input type="password" name="password_actual" autocomplete="current-password"></label><label>Nueva contraseña<input type="password" name="password_nueva" minlength="8" autocomplete="new-password"></label><label>Confirmar nueva contraseña<input type="password" name="password_confirmar" minlength="8" autocomplete="new-password"></label></div><div class="actions"><button type="submit">Guardar cambios</button></div></form></section>
<?php if($esAdmin):?>
<?php if(esSuper()):$clientesAdmin=db()->query('SELECT id,nombre_empresa FROM costobene_clientes WHERE activo=1 ORDER BY nombre_empresa')->fetchAll();?><section class="panel"><label style="max-width:360px">Filtrar usuarios e historial por cliente<select onchange="location.href='perfil.php?cliente='+this.value"><option value="0" <?=$clienteId===0?'selected':''?>>Todos los clientes</option><?php foreach($clientesAdmin as $ca):?><option value="<?=(int)$ca['id']?>" <?=(int)$ca['id']===$clienteId?'selected':''?>><?=h($ca['nombre_empresa'])?></option><?php endforeach;?></select></label></section><?php endif;?>
<section class="panel"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><h2>Usuarios registrados</h2><span class="pill"><?=count($usuarios)?> usuarios</span></div><?php if(!$usuarios):?><div class="empty">No hay otros usuarios registrados en el alcance de tu administración.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Usuario</th><th>Correo</th><th>Rol</th><th>Cliente</th><th>Estado</th></tr></thead><tbody><?php foreach($usuarios as $x):?><tr><td><?=h(trim($x['nombre'].' '.$x['apellido']))?></td><td><?=h($x['nombre_usuario'])?></td><td><?=h($x['correo'])?></td><td><?=h($x['roles']??'—')?></td><td><?=h($x['nombre_empresa'])?></td><td><?=$x['activo']?'Activo':'Inactivo'?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<section class="panel"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><h2>Historial de productos y servicios</h2><span class="pill">Últimos 100 movimientos</span></div><?php if(!$historial):?><div class="empty">Todavía no hay movimientos de productos registrados desde que se activó el historial.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Producto / servicio</th><th>Movimiento</th><th>Usuario</th><th>Detalle</th></tr></thead><tbody><?php foreach($historial as $hrow):$old=json_decode((string)$hrow['datos_anteriores'],true)?:[];$new=json_decode((string)$hrow['datos_nuevos'],true)?:[];$nombre=$new['nombre']??$old['nombre']??('Registro #'.$hrow['registro_id']);?><tr><td><?=h($hrow['fecha_accion'])?></td><td><?=h($nombre)?></td><td><?=['insert'=>'Alta','update'=>'Modificación','delete'=>'Baja'][$hrow['accion']]??h($hrow['accion'])?></td><td><?=h($hrow['usuario_nombre']??$hrow['nombre_usuario']??'Usuario eliminado')?></td><td><?php if($hrow['accion']==='update'):?>Datos anteriores y nuevos registrados.<?php elseif($hrow['accion']==='insert'):?>Producto o servicio creado.<?php else:?>Producto o servicio eliminado.<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php endif;?>
</main></div></body></html>
